:root {
  --bg: #0f1115;
  --surface: #181b22;
  --surface-2: #20242d;
  --border: #2b303b;
  --text: #e6e9ef;
  --muted: #9aa3b2;
  --accent: #6c8cff;
  --accent-hover: #7f9bff;
  --danger: #ff6b6b;
  --radius: 12px;
}

* { box-sizing: border-box; }
[hidden] { display: none !important; }

body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.5;
}

/* Topbar */
.topbar {
  position: sticky;
  top: 0;
  z-index: 10;
  background: rgba(15, 17, 21, 0.9);
  backdrop-filter: blur(8px);
  border-bottom: 1px solid var(--border);
}
.topbar-inner {
  max-width: 1080px;
  margin: 0 auto;
  padding: 14px 20px;
  display: flex;
  align-items: center;
  gap: 16px;
}
.brand {
  font-size: 1.2rem;
  margin: 0;
  white-space: nowrap;
  display: flex;
  align-items: center;
  gap: 8px;
}
.brand-mark { font-size: 1.3rem; }
.search-wrap { flex: 1; }
#search {
  width: 100%;
  padding: 10px 14px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 999px;
  color: var(--text);
  font-size: 0.95rem;
}
#search:focus { outline: none; border-color: var(--accent); }

/* Buttons */
.btn {
  padding: 9px 16px;
  border-radius: 8px;
  border: 1px solid var(--border);
  background: var(--surface-2);
  color: var(--text);
  font-size: 0.9rem;
  cursor: pointer;
  white-space: nowrap;
  transition: background 0.15s, border-color 0.15s;
}
.btn:hover { background: #2a2f3a; }
.btn-primary { background: var(--accent); border-color: var(--accent); color: #fff; }
.btn-primary:hover { background: var(--accent-hover); }

/* Layout */
.container { max-width: 1080px; margin: 0 auto; padding: 24px 20px 64px; }
.count { color: var(--muted); font-size: 0.85rem; margin-bottom: 16px; }

.tag-bar { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 18px; }
.tag-chip {
  padding: 5px 12px;
  border-radius: 999px;
  border: 1px solid var(--border);
  background: var(--surface);
  color: var(--muted);
  font-size: 0.8rem;
  cursor: pointer;
}
.tag-chip:hover { border-color: var(--accent); color: var(--text); }
.tag-chip.active { background: var(--accent); border-color: var(--accent); color: #fff; }

/* Grid */
.grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 16px;
}
.card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 16px 18px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.card-title {
  font-size: 1.02rem;
  font-weight: 600;
  margin: 0;
  word-break: break-word;
}
.card-title a { color: var(--text); text-decoration: none; }
.card-title a:hover { color: var(--accent); }
.card-url {
  font-size: 0.8rem;
  color: var(--accent);
  text-decoration: none;
  word-break: break-all;
}
.card-url:hover { text-decoration: underline; }
.card-desc { font-size: 0.88rem; color: var(--muted); margin: 4px 0 0; word-break: break-word; }
.card-tags { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 4px; }
.card-tag {
  font-size: 0.72rem;
  padding: 3px 9px;
  border-radius: 999px;
  background: var(--surface-2);
  color: var(--muted);
  cursor: pointer;
}
.card-tag:hover { color: var(--text); }
.card-actions {
  display: flex;
  gap: 8px;
  margin-top: auto;
  padding-top: 10px;
  border-top: 1px solid var(--border);
}
.link-btn {
  background: none;
  border: none;
  color: var(--muted);
  font-size: 0.82rem;
  cursor: pointer;
  padding: 2px 4px;
}
.link-btn:hover { color: var(--text); }
.link-btn.danger:hover { color: var(--danger); }

/* Empty */
.empty { text-align: center; padding: 80px 20px; color: var(--muted); }
.empty-title { font-size: 1.1rem; color: var(--text); margin: 0 0 6px; }
.empty-sub { margin: 0; }

/* Modal */
.modal {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.6);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  z-index: 100;
}
.modal-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 24px;
  width: 100%;
  max-width: 460px;
}
.modal-card h2 { margin: 0 0 18px; font-size: 1.15rem; }
.modal-card form { display: flex; flex-direction: column; gap: 14px; }
.modal-card label {
  display: flex;
  flex-direction: column;
  gap: 6px;
  font-size: 0.82rem;
  color: var(--muted);
}
.modal-card input,
.modal-card textarea {
  padding: 10px 12px;
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 8px;
  color: var(--text);
  font-size: 0.92rem;
  font-family: inherit;
  resize: vertical;
}
.modal-card input:focus,
.modal-card textarea:focus { outline: none; border-color: var(--accent); }
.modal-actions { display: flex; justify-content: flex-end; gap: 10px; margin-top: 6px; }
.form-error { color: var(--danger); font-size: 0.83rem; margin: 0; }

@media (max-width: 620px) {
  .topbar-inner { flex-wrap: wrap; }
  .search-wrap { order: 3; flex-basis: 100%; }
}
